// #494e0b (2.3): загрузка синтетических JPEG на шаге 3 мастера и чтение сохранённых файлов (оригинал + ….card3.webp).
// Черновик и очистка — draft-reopen.helpers.ts (#b93c54): пропускаются только запись своего черновика и продление сессии;
// здесь дополнительно пропускается POST storage/v1/object/uploads/* (route.continue — мимо блока записи).
// ПРОД, ПИШУЩИЙ: только QA_REAL_WRITE=1. Файлы storage сайт не удаляет — остаются (имена с QA-AUTO-494e0b) — в отчёт.
import { expect, BrowserContext, Page } from '@playwright/test';
import { LOAD } from '../addbusiness-draft-save/draft-reopen.helpers';

export const STEP3_HEADING = 'העלאת תמונות';
const isUpload = (url: string) => /\/storage\/v1\/object\/uploads\//.test(url);

export type Sample = { tag: 'black-tb' | 'white-lr' | 'nomargin'; w: number; h: number; name: string };
/** A — чёрные поля 300 сверху/снизу; B — белые поля 300 слева/справа; C — контроль без полей. */
export const SAMPLES: Sample[] = [
  { tag: 'black-tb', w: 400, h: 1000, name: 'QA-AUTO-494e0b-black-tb.jpg' },
  { tag: 'white-lr', w: 1000, h: 400, name: 'QA-AUTO-494e0b-white-lr.jpg' },
  { tag: 'nomargin', w: 800, h: 600, name: 'QA-AUTO-494e0b-nomargin.jpg' },
];

export type Upload = { url: string; status: number; path: string };

/** Пропустить загрузки в storage (uploads/*) и записывать их ответы. Вызывать ПОСЛЕ prepare() из draft-reopen.helpers. */
export async function allowUploads(context: BrowserContext): Promise<Upload[]> {
  const uploads: Upload[] = [];
  await context.route((u: URL) => isUpload(u.href), (route) => {
    if (route.request().method() === 'POST') return route.continue();
    return route.fallback();
  });
  context.on('requestfinished', async (r) => {
    if (r.method() !== 'POST' || !isUpload(r.url())) return;
    const res = await r.response();
    uploads.push({ url: r.url(), status: res?.status() ?? 0, path: decodeURIComponent(r.url().split('/storage/v1/object/')[1] || '') });
  });
  context.on('requestfailed', (r) => {
    if (r.method() === 'POST' && isUpload(r.url())) uploads.push({ url: r.url(), status: 0, path: r.url() });
  });
  return uploads;
}

/** Нарисовать JPEG в canvas страницы: цветной «контент» в центре, поля нужного цвета (полосы в пикселях). */
export async function makeJpeg(page: Page, s: Sample): Promise<Buffer> {
  const b64 = await page.evaluate((s) => {
    const c = document.createElement('canvas');
    c.width = s.w;
    c.height = s.h;
    const ctx = c.getContext('2d')!;
    let x = 0, y = 0, w = s.w, h = s.h;
    if (s.tag === 'black-tb') {
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, s.w, s.h);
      y = 300; h = s.h - 600;
    } else if (s.tag === 'white-lr') {
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, s.w, s.h);
      x = 300; w = s.w - 600;
    }
    // Содержимое — пёстрое (градиент + клетки), чтобы его края не считались однотонными.
    const g = ctx.createLinearGradient(x, y, x + w, y + h);
    g.addColorStop(0, '#d9480f');
    g.addColorStop(0.5, '#2b8a3e');
    g.addColorStop(1, '#1864ab');
    ctx.fillStyle = g;
    ctx.fillRect(x, y, w, h);
    for (let i = x; i < x + w; i += 40) for (let j = y; j < y + h; j += 40) {
      if (((i - x) / 40 + (j - y) / 40) % 2 === 0) { ctx.fillStyle = 'rgba(255,214,10,0.55)'; ctx.fillRect(i, j, 20, 20); }
    }
    return c.toDataURL('image/jpeg', 0.92).split(',')[1];
  }, s);
  return Buffer.from(b64, 'base64');
}

/** Загрузить файл в первый input[type=file] (картинки) шага 3 и дождаться загрузки оригинала и card3 (POST uploads/* 200). */
export async function uploadSample(page: Page, uploads: Upload[], s: Sample, buf: Buffer) {
  const before = uploads.length;
  const input = page.locator('input[type=file][accept*="image"]').first();
  await expect(input, 'поле загрузки картинок на шаге 3').toBeAttached(LOAD);
  await input.setInputFiles({ name: s.name, mimeType: 'image/jpeg', buffer: buf });
  await expect
    .poll(() => {
      const mine = uploads.slice(before).filter((u) => u.path.toLowerCase().includes(s.tag));
      const orig = mine.find((u) => !/\.card\d\.webp$/.test(u.path));
      const card3 = mine.find((u) => /\.card3\.webp$/.test(u.path));
      return { orig: orig?.status ?? null, card3: card3?.status ?? null };
    }, { timeout: 45_000, message: `${s.name}: загружены оригинал и ….card3.webp (POST uploads/* 200)` })
    .toEqual({ orig: 200, card3: 200 });
  const mine = uploads.slice(before).filter((u) => u.path.toLowerCase().includes(s.tag));
  return {
    orig: mine.find((u) => !/\.card\d\.webp$/.test(u.path))!,
    card3: mine.find((u) => /\.card3\.webp$/.test(u.path))!,
  };
}

/** Публичный адрес файла storage по адресу загрузки (…/object/uploads/x → …/object/public/uploads/x). */
export const publicUrl = (u: Upload) => u.url.split('?')[0].replace('/storage/v1/object/uploads/', '/storage/v1/object/public/uploads/');

/** Натуральный размер картинки по адресу (загрузка в странице). */
export async function natural(page: Page, url: string): Promise<[number, number] | null> {
  return page.evaluate(
    (u) =>
      new Promise<[number, number] | null>((res) => {
        const i = new Image();
        i.onload = () => res([i.naturalWidth, i.naturalHeight]);
        i.onerror = () => res(null);
        i.src = u + (u.includes('?') ? '&' : '?') + 'qa=' + Date.now();
      }),
    url,
  );
}
